<script setup lang="ts">
import {computed,ref,watch,onMounted,onUnmounted} from 'vue';
import type {Values,Outcome,Control} from '../labs/model';
import UiIcon from './UiIcon.vue';
type Run={values:Values;outcome:Outcome;number:number};
const props=defineProps<{id:number;current:Run;previous?:Run;controls:Control[];generic?:boolean;checkpoint?:string;checkpointAt?:number}>();
const frame=ref(0),playing=ref(false),reduced=ref(false),speed=ref('1');
let timer:ReturnType<typeof setTimeout>|undefined;
let media:MediaQueryList|undefined;
const lanes=computed(()=>props.previous?[props.previous,props.current]:[props.current]);
const end=computed(()=>Math.max(...lanes.value.map(r=>r.outcome.trace.length)));
const finished=computed(()=>frame.value>=end.value);
const title=computed(()=>['事件如何改變案件','部署條件如何改變順位','指令在哪個環境執行','請求在哪一道檢查停下','輸入如何被查詢解讀','同一請求，修補前後','每條規則保護哪個情境','資料跨界時發生什麼','測試能否攔下這次缺陷'][props.id]);
function stop(){clearTimeout(timer);timer=undefined;playing.value=false;}
function schedule(){clearTimeout(timer);if(!playing.value||finished.value)return;timer=setTimeout(()=>{frame.value++;if(finished.value||(props.checkpoint&&frame.value===(props.checkpointAt??1)))stop();else schedule();},1200/Number(speed.value));}
function play(){if(finished.value)frame.value=0;playing.value=true;schedule();}
function replay(){stop();frame.value=reduced.value?end.value:0;if(!reduced.value)play();}
function next(){stop();frame.value=Math.min(end.value,frame.value+1);}
function motionChange(){stop();frame.value=reduced.value?end.value:0;}
function systemMotion(e:MediaQueryListEvent){reduced.value=e.matches;motionChange();}
watch(()=>props.current,replay);
watch(speed,schedule);
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');reduced.value=media.matches;media.addEventListener('change',systemMotion);if(reduced.value)frame.value=end.value;else replay();});
onUnmounted(()=>{stop();media?.removeEventListener('change',systemMotion);});
function skipped(detail:string){return /未執行|前一步停止|未查詢案件內容|未送出|尚未驗證/.test(detail);}
function blocked(detail:string){return !skipped(detail)&&/攔截|拒絕|403|401|資源耗盡|處理失敗/.test(detail);}
function icon(i:number){const sets=[['user','shield','database'],['bug','globe','shield'],['terminal','identity','database'],['globe','identity','shield','database'],['code','shield','database'],['globe','identity','shield','database'],['bookmark','shield','check'],['user','code','database'],['code','lab','shield']] as const;return sets[props.id]?.[i]??'database';}
function label(c:Control,r:Run){const v=r.values[c.key];return typeof v==='boolean'?(v?'開啟':'關閉'):c.options?.find(o=>o[0]===v)?.[1]??String(v);}
function changed(c:Control){return props.previous&&props.previous.values[c.key]!==props.current.values[c.key];}
function shown(r:Run){return frame.value>=r.outcome.trace.length;}
function cardState(r:Run,i:number){if(!shown(r))return 'pending';if(props.id===6||props.id===8){const row=r.outcome.rows[i];return row?.at(-1)==='失敗'?'bad':row?.at(-1)==='未覆蓋'?'skipped':'good';}return r.outcome.tone;}
</script>
<template>
<section class="animated-experiment" :class="{'reduce-motion':reduced,'is-paused':!playing}" aria-label="實驗動畫對照" :data-frame="frame" :data-playing="playing" :style="{'--step-time':`${1.2/Number(speed)}s`}">
<div class="animation-heading"><div><span class="eyebrow">{{previous?'同步對照 · 最近兩次執行':'流程觀察 · 第一次執行'}}</span><h3>{{generic?'追蹤處理與後續影響':title}}</h3></div><span class="frame-label">{{frame}} / {{end}}</span></div>
<div class="animation-toolbar"><button type="button" @click="playing?stop():play()" :disabled="reduced">{{playing?'暫停動畫':finished?'重播動畫':'播放動畫'}}</button><button type="button" @click="next" :disabled="finished">前進一步</button><button type="button" @click="stop();frame=0">回到起點</button><button type="button" @click="stop();frame=end">直接看結果</button><label>速度 <select v-model="speed" aria-label="動畫速度"><option value="0.5">0.5×</option><option value="1">1×</option><option value="2">2×</option></select></label><label class="motion-toggle"><input type="checkbox" v-model="reduced" @change="motionChange">減少動態效果</label></div>
<p class="animation-help">{{previous?'兩邊依同一時間軸播放，標記的條件是這次改動。':'先觀察這次處理路徑；改變條件再執行，就會出現並排對照。'}}{{reduced?'目前使用靜態呈現，也可回到起點逐步查看。':''}}</p>
<p v-if="checkpoint&&frame===(checkpointAt??1)" class="checkpoint-question" role="status">檢查點：{{checkpoint}} 請先想一想，再按「播放動畫」或「前進一步」。</p>
<div class="animation-lanes" :class="{single:!previous}">
<article v-for="(r,lane) in lanes" :key="r.number" class="animation-lane" :aria-label="`第 ${r.number} 次執行動畫`">
<div class="lane-heading"><strong>{{previous?(lane===0?'前一次':'這一次'):'這一次'}}</strong><span>第 {{r.number}} 次</span></div>
<div class="condition-chips"><span v-for="c in controls" :key="c.key" :class="{changed:changed(c)}">{{c.label}}：{{label(c,r)}}<b v-if="changed(c)"> · 已變更</b></span></div>
<ol class="animated-path"><li v-for="([step,detail],i) in r.outcome.trace" :key="step" :class="{revealed:frame>i,active:frame===i+1,blocked:frame>i&&blocked(detail),skipped:frame>i&&skipped(detail)}">
<div class="flow-icon"><UiIcon :name="icon(i)" :size="28"/><span class="flow-state">{{frame<=i?'':skipped(detail)?'—':blocked(detail)?'■':'✓'}}</span></div><div class="flow-copy"><strong>{{step}}</strong><p>{{frame>i?detail:'等待前一步'}}</p></div><span v-if="i<r.outcome.trace.length-1" class="flow-wire" :class="{travelling:frame===i+1&&!skipped(detail)&&!blocked(detail),stopped:frame>i&&blocked(detail)}" aria-hidden="true"><i/></span>
</li></ol>
<div class="animated-impact" :class="shown(r)?r.outcome.tone:'pending'" :data-result-visible="shown(r)">
<template v-if="generic"><h4>實際影響與證據</h4><div v-if="shown(r)" class="deep-result-table"><table><thead><tr><th v-for="column in r.outcome.columns" :key="column">{{column}}</th></tr></thead><tbody><tr v-for="(row,i) in r.outcome.rows" :key="i"><td v-for="(cell,j) in row" :key="j">{{cell}}</td></tr></tbody></table></div><p v-else>等待流程完成後，比對實際資料與後續影響。</p></template>
<template v-else-if="id===0"><h4>案件發生了什麼變化？</h4><div class="impact-tiles"><div v-for="row in r.outcome.rows" :key="row[0]"><small>{{row[0]}}</small><strong>{{shown(r)?row[2]:row[1]}}</strong><span>{{shown(r)&&row[1]!==row[2]?`${row[1]} → ${row[2]}`:'維持原狀'}}</span></div></div></template>
<template v-else-if="id===1"><h4>修補順位</h4><div class="rank-stage"><div v-for="name in ['A 報表服務','B 案件 API']" :key="name" class="rank-item" :style="{transform:`translateY(${(shown(r)?r.outcome.rows.findIndex(row=>row[1]===name):['A 報表服務','B 案件 API'].indexOf(name))*52}px)`}"><b>{{shown(r)?r.outcome.rows.findIndex(row=>row[1]===name)+1:'?'}}</b>{{name}}</div></div></template>
<template v-else-if="id===2"><h4>{{r.values.host==='remote'?'遠端測試 VM':'本機開發環境'}}</h4><pre class="animated-terminal">{{shown(r)?r.outcome.code:'$ 等待指令執行…'}}</pre></template>
<template v-else-if="id===3||id===5||id===4"><h4>{{id===4?'查詢回傳資料':'使用者收到的內容'}}</h4><div class="data-envelope" :class="{delivered:shown(r)&&r.outcome.rows.length,empty:shown(r)&&!r.outcome.rows.length}"><UiIcon :name="shown(r)&&!r.outcome.rows.length?'shield':'database'" :size="35"/><span>{{shown(r)?`${r.outcome.rows.length} 筆資料`:'等待處理'}}</span></div><div v-if="shown(r)" class="record-chips"><span v-for="row in r.outcome.rows" :key="row[0]">{{row.join(' · ')}}</span><span v-if="!r.outcome.rows.length">沒有回傳案件內容</span></div></template>
<template v-else-if="id===6||id===8"><h4>{{id===6?'安全規則驗收':'CI 測試與發布'}}</h4><div class="test-lights"><div v-for="(row,i) in r.outcome.rows" :key="row[0]" :class="cardState(r,i)"><span>{{shown(r)?row.at(-1):'等待'}}</span><strong>{{row[0]}}</strong><small v-if="shown(r)">{{row[1]}}</small></div></div></template>
<template v-else><h4>文件處理結果</h4><div class="data-envelope" :class="{delivered:shown(r)&&r.outcome.signature==='exposed',empty:shown(r)&&r.outcome.signature==='mitigated'}"><UiIcon :name="shown(r)&&r.outcome.signature==='mitigated'?'shield':'graph'" :size="40"/><span>{{shown(r)?r.outcome.signature==='mitigated'?'威脅已攔截':'威脅造成影響':'文件沿邊界處理中'}}</span></div></template>
<p class="animation-verdict">{{shown(r)?r.outcome.title:'播放流程，觀察結果如何形成。'}}</p><p v-if="shown(r)" class="impact-summary">{{r.outcome.summary}}</p>
</div>
</article></div>
<p class="animation-status" role="status">{{finished?'動畫播放完成，可重播或改變條件再次執行。':playing?'流程播放中。':'動畫已暫停，可逐步前進。'}}</p>
</section>
</template>
<style scoped>
.checkpoint-question{padding:16px;border-left:3px solid #b98630;background:#fff7df;line-height:1.9;font-size:14px}.deep-result-table{overflow-x:auto}.deep-result-table table{width:100%;border-collapse:collapse;font-size:12px;line-height:1.8}.deep-result-table th,.deep-result-table td{padding:8px;text-align:left;border-bottom:1px solid #d4e2e8;overflow-wrap:anywhere}
.animated-experiment{margin:18px 0 24px;padding:22px;border:1px solid #c4dae7;border-radius:12px;background:#f8fcff;--step-time:1.2s}.animation-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.animation-heading h3{font-size:20px;line-height:1.6;margin:7px 0 14px}.frame-label{font-variant-numeric:tabular-nums;white-space:nowrap;font-size:13px;color:#416079}.animation-toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.animation-toolbar button,.animation-toolbar select{padding:8px 12px;min-height:40px;border:1px solid #a9c9dc;background:white;border-radius:6px;font:inherit;font-size:13px;color:#19314d}.animation-toolbar button:disabled{opacity:.45;cursor:default}.animation-toolbar label{display:flex;align-items:center;gap:6px;font-size:12px}.animation-toolbar input{width:17px;height:17px;accent-color:#007da6}.animation-help{font-size:13px;line-height:1.8;color:#557087}.animation-lanes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.animation-lanes.single{grid-template-columns:1fr}.animation-lane{min-width:0;background:white;border:1px solid #d1e2ec;border-radius:10px;overflow:hidden}.lane-heading{display:flex;justify-content:space-between;padding:14px 18px;background:#eaf4fa;color:#244a66;font-size:14px}.lane-heading>span{font-size:12px}.condition-chips{padding:14px 16px;display:flex;flex-wrap:wrap;gap:6px;min-height:68px;align-content:start}.condition-chips>span{font-size:11px;line-height:1.6;border:1px solid #e0e9ef;border-radius:4px;padding:4px 7px;overflow-wrap:anywhere}.condition-chips .changed{border-color:#bb8631;background:#fff6df}.animated-path{list-style:none;margin:0;padding:5px 18px 12px}.animated-path li{display:flex;align-items:start;gap:14px;position:relative;min-height:106px;padding:12px 0 23px;opacity:.4;transition:opacity .3s}.animated-path li.revealed{opacity:1}.flow-icon{width:45px;height:45px;flex-shrink:0;display:grid;place-items:center;border:1px solid #bad2e2;background:#f4f8fb;border-radius:10px;position:relative;z-index:1}.active .flow-icon{background:#dbf4fb;border-color:#008fb8;box-shadow:0 0 0 4px #dbf4fb}.blocked .flow-icon{background:#fff2df;border-color:#b57a22}.skipped .flow-icon{border-style:dashed;background:#f0f2f3}.flow-state{position:absolute;right:-5px;bottom:-6px;background:white;font-size:12px;border-radius:50%;color:#326b58}.blocked .flow-state{color:#a2641a}.flow-copy{min-width:0}.flow-copy strong{font-size:14px;line-height:1.6}.flow-copy p{font-size:12px;line-height:1.8;margin:6px 0 0;color:#547084;overflow-wrap:anywhere;min-height:40px}.flow-wire{position:absolute;top:57px;bottom:-12px;left:22px;border-left:2px solid #d4e5ef}.flow-wire i{position:absolute;top:0;left:-5px;width:8px;height:8px;border-radius:50%;background:#009bc0;opacity:0}.travelling i{animation:packet var(--step-time) linear infinite}.stopped{border-left:2px dashed #b88436}.stopped:after{content:'■';position:absolute;left:-5px;top:12px;color:#b88436;font-size:9px}.animated-impact{margin:0 16px 16px;padding:16px;background:#eff5f9;border:1px solid #d6e4ec;border-radius:8px;min-height:190px}.animated-impact.good{background:#edf8f1;border-color:#afd3bf}.animated-impact.bad{background:#fff3e9;border-color:#e2bf9e}.animated-impact h4{font-size:13px;margin:0 0 16px}.impact-tiles{display:grid;gap:8px}.impact-tiles>div{display:flex;align-items:center;gap:12px;padding:10px;background:#ffffffb8;border-radius:6px;flex-wrap:wrap}.impact-tiles small{flex:1;font-size:12px}.impact-tiles strong{font-size:17px}.impact-tiles span{font-size:11px;color:#637684}.rank-stage{height:104px;position:relative}.rank-item{position:absolute;top:0;left:0;right:0;height:44px;display:flex;align-items:center;gap:12px;padding:10px;background:white;border:1px solid #c4dce9;border-radius:6px;transition:transform .7s;font-size:13px}.rank-item b{display:grid;place-items:center;width:23px;height:23px;background:#dff1fa;border-radius:50%;color:#006d90}.animated-terminal{background:#19314d;color:#edf8ff;padding:14px;font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;border-radius:6px}.data-envelope{display:flex;align-items:center;justify-content:center;gap:12px;min-height:80px;color:#45697f}.data-envelope.delivered{animation:arrive .5s ease-out;color:#246f89}.bad .data-envelope.delivered{color:#a95c2e}.data-envelope.empty{color:#28785e}.record-chips{display:flex;flex-wrap:wrap;gap:7px}.record-chips span{padding:7px 9px;background:white;border:1px solid #d8e5ea;border-radius:5px;font-size:12px}.test-lights{display:grid;gap:8px}.test-lights>div{padding:10px;background:#ffffffae;border-left:3px solid #b9ccd9;display:flex;gap:8px;flex-wrap:wrap;align-items:center}.test-lights strong{font-size:12px}.test-lights span{font-size:11px}.test-lights small{font-size:11px;width:100%;color:#4d677a}.test-lights .good{border-color:#3d886b}.test-lights .bad{border-color:#c56c35}.test-lights .skipped{border-style:dashed}.animation-verdict{font-size:15px;font-weight:600;line-height:1.7;margin:16px 0 0}.impact-summary,.animation-status{font-size:12px;line-height:1.8;color:#516d81}.animation-status{margin-bottom:0}.is-paused .flow-wire i{animation-play-state:paused!important}.reduce-motion *{animation:none!important;transition:none!important}@keyframes packet{0%{top:0;opacity:1}90%{opacity:1}100%{top:100%;opacity:0}}@keyframes arrive{from{transform:translateY(-15px);opacity:.3}to{transform:translateY(0);opacity:1}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}@media(max-width:1100px) and (min-width:701px){.animation-lanes{grid-template-columns:1fr}}@media(max-width:700px){.animated-experiment{padding:14px}.animation-lanes{grid-template-columns:1fr}.animation-heading h3{font-size:18px}.animation-toolbar button{flex-grow:1}.animation-lane{scroll-margin-top:15px}}
</style>
